CREATE TABLE "AppSetting" ("key" TEXT PRIMARY KEY, "value" TEXT NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "User" ("id" TEXT PRIMARY KEY, "email" TEXT NOT NULL UNIQUE, "name" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "role" TEXT NOT NULL DEFAULT 'admin', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Workspace" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "color" TEXT NOT NULL DEFAULT 'cyan', "ownerId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "BrainItem" ("id" TEXT PRIMARY KEY, "title" TEXT NOT NULL, "type" TEXT NOT NULL, "description" TEXT, "url" TEXT, "filePath" TEXT, "mimeType" TEXT, "size" INTEGER, "x" DOUBLE PRECISION NOT NULL DEFAULT 50, "y" DOUBLE PRECISION NOT NULL DEFAULT 50, "color" TEXT NOT NULL DEFAULT 'cyan', "tags" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], "dueAt" TIMESTAMP(3), "isCompleted" BOOLEAN NOT NULL DEFAULT false, "isArchived" BOOLEAN NOT NULL DEFAULT false, "deletedAt" TIMESTAMP(3), "workspaceId" TEXT NOT NULL REFERENCES "Workspace"("id") ON DELETE CASCADE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY, "action" TEXT NOT NULL, "detail" TEXT, "userId" TEXT REFERENCES "User"("id") ON DELETE SET NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "BrainItem_workspaceId_idx" ON "BrainItem"("workspaceId");
